/// of it, and no hazard row, translation gate or codex entry is owed for it.
fn basis_species_data(key: &str) -> Option<&'static SpeciesData> {
    if key != BASE_EQUIVALENTS {
        return None;
    }
    use std::sync::OnceLock;
    static BASIS: OnceLock<&'static SpeciesData> = OnceLock::new();
    Some(*BASIS.get_or_init(|| {
        let mut data = lookup_index()
            .get("OH-")
            .copied()
            .expect("the registry defines the hydroxide ion")
            .clone();
        data.key = BASE_EQUIVALENTS;
        data.name = "base equivalents";
        // Not a substance, so it has no substance identity. An InChIKey
        // here would claim this slot IS hydroxide, which is the claim the
        // rename exists to withdraw.
        data.inchikey = "";
        data.provenance = "Analytical aqueous basis coordinate: the base half of the \
                           acid/base equivalents that close a solved vessel's H/O \
                           balance. Stoichiometry and mass are the registry's OH- row \
                           because one equivalent is one OH by construction; this is \

pub solution: Option<SolutionInfo>,
/// ARCH-004: Material lots tracking provenance of additions.
#[serde(default, skip_serializing_if = "Vec::is_empty")]
pub lots: Vec<MaterialLot>,
/// ARCH-005: Solver-derived state, invalidated on mutation.
#[serde(default)]
pub resolved: ResolvedState,
/// The source key ([`Provenance::source_key`]) of the aqueous routing
/// this vessel has already been told about.
///
/// `Event::SolutionRouted` fires on CHANGE, and this is what "change"
/// is measured against. It has to live on the vessel rather than in
/// the solver, because the thermal fixed point solves a CLONE of the
/// vessel up to eight times per step and keeps only the last one's
/// events: memory held in the solver would announce on the first pass
/// and then be silent on the pass whose events actually survive.
/// Cloned with the vessel, it is the same for every trial, so every
/// trial reaches the same verdict and the surviving one carries it.
///
/// It is deliberately NOT the provenance already on
/// `solution.provenance`, which is a different question. That field is
/// the CURRENT source, and a later solver in the stack may nest its
/// own clause into it — the electrode pass in `displacement.rs` does

#[serde(default)]
pub pending_co2_transfer_mol: f64,
/// `Some` once an aqueous solver has characterised the solution; `None`
/// means no solver has — and the honesty pass says so.
#[serde(default)]
pub solution: Option<SolutionInfo>,
/// ARCH-004: Material lots tracking provenance of additions.
#[serde(default, skip_serializing_if = "Vec::is_empty")]
pub lots: Vec<MaterialLot>,
/// ARCH-005: Solver-derived state, invalidated on mutation.
#[serde(default)]
pub resolved: ResolvedState,
/// The source key ([`Provenance::source_key`]) of the aqueous routing
/// this vessel has already been told about.
///
/// `Event::SolutionRouted` fires on CHANGE, and this is what "change"
/// is measured against. It has to live on the vessel rather than in
/// the solver, because the thermal fixed point solves a CLONE of the
/// vessel up to eight times per step and keeps only the last one's
/// events: memory held in the solver would announce on the first pass
/// and then be silent on the pass whose events actually survive.
/// Cloned with the vessel, it is the same for every trial, so every
/// trial reaches the same verdict and the surviving one carries it.

fn titrate_loop(
    &mut self,
    op: Operator,
    solver: &mut dyn Equilibrator,
    screen: &dyn SafetyScreen,
) -> Result<Vec<Event>, BenchError> {
    let (vessel, titrant, concentration, step, target_ph, max_steps, endpoint) = match &op {
        Operator::Titrate {
            vessel,
            titrant,
            concentration,
            step,
            target_ph,
            max_steps,
            endpoint,
        } => (
            *vessel,
            titrant.clone(),
            *concentration,
            *step,
            *target_ph,
            *max_steps,
            *endpoint,
        ),
        _ => unreachable!(),
    };

    // Validate the individual inputs before multiplication: two negative
    // factors must not manufacture a positive dose, and NaN must not pass
    // through an ordered comparison. No endpoint range is invented here.
    if !concentration.is_finite() || !step.0.is_finite() || !target_ph.is_finite() {
        return Err(BenchError::InvalidState(
            "titration concentration, volume and pH target must be finite".into(),
        ));
    }
    if concentration <= 0.0 || step.0 <= 0.0 {
        return Err(BenchError::NonPositiveAmount);
    }
    self.validate_numeric_state()?;

    let data =
        species::lookup(&titrant).ok_or_else(|| BenchError::UnknownSpecies(titrant.clone()))?;
    // The burette holds a standard solution: each step delivers
    // concentration × volume moles of titrant, carried by the water
    // of the step volume. (Delivering the *pure* substance by volume
    // — the previous reading — doses ~50× per mL for NaOH and leaps
    // the whole curve in one step; no practical is run that way.)
    let moles_per_step = Moles(concentration * step.0);
    let water = SpeciesId::new("water");
    let water_data =
        species::lookup(&water).ok_or_else(|| BenchError::UnknownSpecies(water.clone()))?;
    let water_per_step = water_data.moles_from_liters(step);
    if !moles_per_step.0.is_finite() || !water_per_step.0.is_finite() {
        return Err(BenchError::InvalidState(
            "titration dose and carrier amount must be finite".into(),
        ));
    }
    if moles_per_step.0 <= 0.0 || water_per_step.0 <= 0.0 {
        return Err(BenchError::NonPositiveAmount);
    }

    let mut events = Vec::new();
    let mut curve: Vec<(f64, f64)> = Vec::new();
    // EXP-39: the redox half of the same curve, sparse by design —
    // a step where the engine withholds pe contributes no point,
    // because at equivalence pe is undefined rather than large.
    let mut pe_curve: Vec<(f64, f64)> = Vec::new();

    // Read initial pH if available.
    {
        let v = self.vessel(vessel)?;
        if let Some(info) = &v.solution {
            curve.push((0.0, info.ph));
            if let Some(pe) = info.pe {
                pe_curve.push((0.0, pe));
            }
        }
    }

    // EXP-39: the flask as the eye finds it before the first drop.
    // A self-indicating endpoint is a *change* from this, not an
    // absolute colour — a titration into an already-yellow solution
    // still has an endpoint, and hard-coding "not colourless" would
    // have declared it reached before the burette was opened.
    let baseline_colour = liquid_colour_word_of(self.vessel(vessel)?);

    let mut total_volume = Liters(0.0);
    let mut reached = false;
    let mut pe_ever_pinned = false;

    // Every trial starts from the SAME pre-increment inventory. This avoids
    // accumulating matter, heat or gas-exchange events during root finding.
    enum TrialFailure {
        Invalid(BenchError),
        Veto(String),
        Solver(crate::solve::SolveError),
    }
    let validate_trial = |v: &Vessel| {
        let errors = crate::delta::StateDelta::validate_state(v);
        if errors.is_empty() {
            Ok(())
        } else {
            Err(TrialFailure::Invalid(BenchError::InvalidState(
                errors
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>()
                    .join("; "),
            )))
        }
    };
    let dose = |start: &Vessel, fraction: f64, solver: &mut dyn Equilibrator| {
        let mut v = start.clone();
        if matches!(v.thermal_mode, ThermalMode::Adiabatic) {
            // Main integrates each side along its own Cp(T) rather than
            // multiplying two flat rectangles, and this dose is a FRACTION
            // of the increment while the root is being found — so the
            // enthalpy it carries in is that fraction too. Charging a whole
            // increment's heat for a tenth of a drop moves the very curve
            // the bisection is reading.
            let settled = adiabatic_mix_into(&v, Kelvin::STANDARD, |t| {
                portions_enthalpy(
                    [
                        (&titrant, fraction * moles_per_step.0, data.standard_phase),
                        (&water, fraction * water_per_step.0, Phase::Liquid),
                    ],
                    Kelvin::STANDARD.0,
                    t,
                )
            });
            v.temperature = settled;
        }
        v.deposit(
            titrant.clone(),
            Moles(fraction * moles_per_step.0),
            data.standard_phase,
        );
        v.deposit(
            water.clone(),
            Moles(fraction * water_per_step.0),
            Phase::Liquid,
        );
        v.solution = None;
        v.step_start = Some(crate::vessel::StepStart::capture(&v));
        // Both the full dose and every refinement candidate are checked
        // before safety, applicability or equilibrium hooks see them.
        validate_trial(&v)?;
        let mut trial_events = Vec::new();
        match screen.assess(&v) {
            SafetyVerdict::Allow => {}
            SafetyVerdict::Warn {
                severity,
                rule,
                hazard,
                real_world,
            } => {
                trial_events.push(Event::HazardWarning {
                    severity,
                    rule,
                    hazard,
                    real_world,
                });
            }
            SafetyVerdict::Veto { reason } => return Err(TrialFailure::Veto(reason)),
        }
        let before_solve = v.clone();
        let result = if solver.applies(&v) {
            solver.equilibrate(&mut v)
        } else {
            Ok(Vec::new())
        };
        v.step_start = None;
        v.heat_input = None;
        v.refresh_pressure();
        let mut solved_events = result.map_err(TrialFailure::Solver)?;
        validate_trial(&v)?;
        // Keep settled-state hazards with this private trial. Refinement
        // discards the full-dose events when it accepts a smaller dose.
        match screen.assess_equilibrated(&before_solve, &v) {
            SafetyVerdict::Allow => {}
            SafetyVerdict::Warn {
                severity,
                rule,
                hazard,
                real_world,
            } => {
                trial_events.push(Event::HazardWarning {
                    severity,
                    rule,
                    hazard,
                    real_world,
                });
            }
            SafetyVerdict::Veto { reason } => return Err(TrialFailure::Veto(reason)),
        }
        trial_events.append(&mut solved_events);
        Ok((v, trial_events))
    };

    for _ in 0..max_steps {
        let start = self.vessel(vessel)?.clone();
        if matches!(endpoint, Endpoint::Ph)
            && start
                .solution
                .as_ref()
                .is_some_and(|s| (s.ph - target_ph).abs() <= 1e-4)
        {
            reached = true;
            break;
        }
        let (mut accepted, mut accepted_events) = match dose(&start, 1.0, solver) {
            Ok(result) => result,
            Err(TrialFailure::Invalid(error)) => return Err(error),
            Err(TrialFailure::Veto(reason)) => return Ok(vec![Event::SafetyVeto { reason }]),
            Err(TrialFailure::Solver(e)) => {
                events.push(Event::SolverFailed {
                    vessel,
                    solver: solver.name().to_string(),
                    detail: e.to_string(),
                });
                break;
            }
        };
        let mut fraction = 1.0;
        let mut refined = false;
        if let (Endpoint::Ph, Some(before), Some(after)) =
            (endpoint, &start.solution, &accepted.solution)
        {
            let mut lo_value = before.ph - target_ph;
            if lo_value * (after.ph - target_ph) <= 0.0 {
                let (mut lo, mut hi) = (0.0, 1.0);
                let mut error = (after.ph - target_ph).abs();
                for _ in 0..48 {
                    if error <= 1e-4 {
                        break;
                    }
                    let mid = 0.5 * (lo + hi);
                    let (trial, trial_events) = match dose(&start, mid, solver) {
                        Ok(result) => result,
                        Err(TrialFailure::Invalid(error)) => return Err(error),
                        Err(TrialFailure::Veto(reason)) => {
                            return Ok(vec![Event::SafetyVeto { reason }]);
                        }
                        Err(TrialFailure::Solver(_)) => break,
                    };
                    let Some(info) = &trial.solution else {
                        break;
                    };
                    let value = info.ph - target_ph;
                    if !value.is_finite() {
                        break;
                    }
                    if lo_value * value <= 0.0 {
                        hi = mid;
                    } else {
                        lo = mid;
                        lo_value = value;
                    }
                    if value.abs() < error {
                        error = value.abs();
                        fraction = mid;
                        accepted = trial;
                        accepted_events = trial_events;
                    }
                }
                refined = error <= 1e-4;
                if !refined {
                    events.push(Event::not_modeled(
                                    vessel,
                                    crate::ops::NotModelledCause::ModelBoundary,
                                    Phrase::bare(
                                        "not-modeled.titration-endpoint-not-refined",
                                        "pH crossing bracketed, but endpoint refinement did not converge to 0.0001 pH; the closest computed state is retained",
                                    ),
                                ));
                }
            }
        }
        *self.vessel_mut(vessel)? = accepted;
        events.append(&mut accepted_events);
        total_volume = Liters(total_volume.0 + step.0 * fraction);

        // Read pH after this step.
        let v = self.vessel(vessel)?;
        // The colour is read from the same equilibrated vessel, so a
        // colour seen here is a colour that stays: the endpoint of a
        // self-indicating titration is a statement about equilibrium,
        // not about how long you stand and watch.
        let colour = liquid_colour_word_of(v);
        match &v.solution {
            Some(info) => {
                let ml = total_volume.0 * 1000.0;
                let ph = info.ph;
                curve.push((ml, ph));
                if let Some(pe) = info.pe {
                    pe_curve.push((ml, pe));
                    pe_ever_pinned = true;
                }
                let arrived = match endpoint {
                    Endpoint::Ph => refined || (ph - target_ph).abs() <= 1e-4,
                    Endpoint::Pe { compare, value } => {
                        info.pe.is_some_and(|pe| compare.holds(pe, value))
                    }
                    Endpoint::ColourPersists => colour != baseline_colour,
                };
                if arrived {
                    reached = true;
                    break;
                }
            }
            None => {
                // Without a characterised solution there is no pH and
                // no speciation, so no endpoint of any kind can be
                // read. The colour endpoint is the one exception worth
                // naming: it is read off the vessel, not the solve —
                // but an unsolved vessel holds the titrant as the
                // solid it was added as, and a solid has no ε(λ).
                events.push(Event::not_modeled(
                    vessel,
                    crate::ops::NotModelledCause::NoSolver,
                    Phrase::bare(
                        "not-modeled.titration-needs-an-aqueous-solver",
                        "titration needs an aqueous solver to compute pH \
                           after each addition — none is wired",
                    ),
                ));
                break;
            }
        }
    }

    // CAP-12 promised a titration that "refuses politely when no
    // endpoint is reachable and says why". The pH endpoint keeps its
    // original silence — changing it would rewrite curves that are
    // already pinned — but the EXP-39 endpoints say so, and say which
    // of the two ways they failed: the target was never met, or, for
    // the potentiometric one, no potential was ever definable at all.
    // Those are different findings and a reader is owed the difference:
    // a flask holding only the reduced half of a couple has no
    // potential, and reporting that as "pe never got high enough"
    // would invent a measurement to explain a missing one.
    if !reached && !curve.is_empty() {
        // `{steps}` is a COUNT, `{target}` is the comparison as the
        // reader typed it (`>=`, a number) — notation, not words —
        // and the liquid's colour is an appearance word, which is
        // exactly the distinction a flat `format!` could not carry.
        let steps = || ("steps".to_string(), Slot::number(max_steps.to_string()));
        let target = |compare: crate::ops::Compare, value: f64| {
            (
                "target".to_string(),
                Slot::text(format!("{} {value}", compare.symbol())),
            )
        };
        let reason = match endpoint {
            Endpoint::Ph => None,
            Endpoint::Pe { compare, value } if !pe_ever_pinned => Some(Phrase::new(
                "not-modeled.titration-pe-never-pinned",
                "the burette ran to its {steps}-step limit without reaching \
                 pe {target}: no potential was pinned at any point in this \
                 titration. With only one oxidation state of a couple in the \
                 flask the electron balance has no root, so pe is undefined \
                 rather than low — add the other half of a redox couple, or \
                 titrate to a colour instead",
                vec![steps(), target(compare, value)],
            )),
            Endpoint::Pe { compare, value } => Some(Phrase::new(
                "not-modeled.titration-pe-out-of-reach",
                "the burette ran to its {steps}-step limit without reaching \
                 pe {target}; the last potential this flask pinned was {last}",
                vec![
                    steps(),
                    target(compare, value),
                    (
                        "last".to_string(),
                        Slot::number(format!(
                            "{:.2}",
                            pe_curve.last().map(|&(_, pe)| pe).unwrap_or(f64::NAN)
                        )),
                    ),
                ],
            )),
            Endpoint::ColourPersists => Some(Phrase::new(
                "not-modeled.titration-colour-persists",
                "the burette ran to its {steps}-step limit and the liquid is \
                 still {colour}: either the endpoint is further away \
                 than {steps} increments, or nothing here carries a curated \
                 absorption spectrum for the eye to read. Raise `max`, or \
                 titrate to a pH or a pe instead",
                vec![
                    steps(),
                    (
                        "colour".to_string(),
                        Slot::term("appearance", baseline_colour),
                    ),
                ],
            )),
        };
        if let Some(reason) = reason {
            events.push(Event::not_modeled(
                vessel,
                crate::ops::NotModelledCause::ModelBoundary,
                reason,
            ));
        }
    }

    let final_ph = curve.last().map(|&(_, p)| p).unwrap_or(f64::NAN);
    let step_count = if curve.is_empty() {
        0
    } else {
        (curve.len() as u32).saturating_sub(1)
    };

    if step_count > 0 || reached {
        events.push(Event::Titrated {
            vessel,
            titrant,
            concentration,
            steps: step_count,
            total_volume,
            final_ph,
            curve,
            pe_curve,
            endpoint_reached: Some(reached),
            endpoint,
        });
    }

    self.log.push(LogEntry {
        step: self.log.len(),
        operator: op,
        events: events.clone(),
    });
    Ok(events)
}
